// Assemble the mailstack /v1/send body from Configuration, keeping baseUrl/apiKey
// out of it (those configure the HTTP request itself, not the email content).
const c = $input.first().json;
const body = {
  brand: c.brand,
  template: c.template,
  to: c.to,
  name: c.name,
  amount: c.amount,
  currency: c.currency,
  item: c.item,
  orderId: c.orderId,
  date: c.date,
  invoiceUrl: c.invoiceUrl,
  orderUrl: c.orderUrl,
};
return [{ json: { baseUrl: c.baseUrl, apiKey: c.apiKey, body } }];
